R += [
 dict(key='testdaten', title=('Testdaten (Plugin)','Test data (plugin)'),
  lead=('Erzeugt 1.000 Testkunden mit Namen, Adressen, IBAN und Geburtsdatum und pseudonymisiert echte Kundendaten: Gleiche Kundennummern bekommen dieselbe Ersatznummer, auch über Tabellen und Läufe hinweg. Mit dem Plugin <code>faker</code>.','Generates 1,000 test customers with names, addresses, IBAN and birth date and pseudonymizes real customer data: equal customer numbers get the same replacement, across tables and runs too. With the <code>faker</code> plugin.'),
  apiLabel=('Plugin','Plugin'),
  api=('<a href="https://github.com/runnelhq/plugin-faker"><code>runnelhq/plugin-faker</code></a>: Eingabe <code>faker.rows</code>, Transform <code>faker.fill</code>, Action <code>faker.value</code>; gebaut mit dem Rust-SDK','<a href="https://github.com/runnelhq/plugin-faker"><code>runnelhq/plugin-faker</code></a>: input <code>faker.rows</code>, transform <code>faker.fill</code>, action <code>faker.value</code>; built with the Rust SDK'),
  auth=('keine – rechnet nur lokal','none – computes locally only'),
  prereq=[('plugins/faker','Plugin','Archiv von den <a href="https://github.com/runnelhq/plugin-faker/releases">Releases</a> nach <code>plugins/</code> entpacken und mit <code>runnel plugins trust</code> freigeben – siehe <a href="plugins.html#installieren">Plugins installieren</a>','Unpack the archive from the <a href="https://github.com/runnelhq/plugin-faker/releases">releases</a> into <code>plugins/</code> and trust it with <code>runnel plugins trust</code> – see <a href="plugins.html#install">Installing plugins</a>'),
          ('PSEUDONYM_SEED','Variable','Schlüssel der Pseudonyme, eine ganze Zahl – als Umgebungsvariable, nie im Projekt','Key of the pseudonyms, a whole number – as an environment variable, never in the project')],
  files=['project.yaml','data/customers.csv','pipelines/customers.pipeline.yaml','pipelines/pseudonymize.pipeline.yaml','workflows/generate.workflow.yaml'],
  run=['Expand-Archive .\\runnel-plugin-faker_<version>_windows_amd64.zip -DestinationPath .\\plugins','runnel plugins trust . --plugin faker','$env:PSEUDONYM_SEED = "…"   # eine ganze Zahl','runnel run workflows/generate.workflow.yaml','runnel run --param COUNT=100000 pipelines/customers.pipeline.yaml'],
  adapt=[('Felder wählt <code>kind</code>: Personen (<code>firstName</code>, <code>salutation</code> passend zum Vornamen), Adressen mit echten Städten und passender Postleitzahl, <code>iban</code>, <code>bic</code> und <code>vatId</code> mit gültiger Prüfziffer, Zahlen und Daten mit <code>min</code>/<code>max</code>, <code>pick</code> mit Gewichten und <code>pattern</code> wie <code>KD-#####</code>. <code>nullRate</code> erzeugt leere Werte, um Wege für fehlende Daten zu testen.','<code>kind</code> chooses the fields: people (<code>firstName</code>, <code>salutation</code> matching the first name), addresses with real cities and matching postcodes, <code>iban</code>, <code>bic</code> and <code>vatId</code> with valid check digits, numbers and dates with <code>min</code>/<code>max</code>, <code>pick</code> with weights and <code>pattern</code> such as <code>KD-#####</code>. <code>nullRate</code> produces empty values to test paths for missing data.'),
         ('<code>seed</code> macht Testdaten wiederholbar: gleiche Konfiguration, gleiche Daten auf jedem System. Ein neues Feld ändert die anderen nicht. <code>locale: en</code> erzeugt englische Daten.','<code>seed</code> makes test data repeatable: same configuration, same data on every system. A new field does not change the others. <code>locale: en</code> produces English data.'),
         ('Für einen einzelnen Wert im Workflow, etwa für einen Test: Action <code>faker.value</code> mit <code>kind: iban</code>; das Ergebnis steht in <code>results.&lt;id&gt;.output</code>.','For a single value in a workflow, e.g. for a test: action <code>faker.value</code> with <code>kind: iban</code>; the result is in <code>results.&lt;id&gt;.output</code>.')],
  note=('Mit <code>consistent: true</code> hängt der Ersatz nur vom Eingabewert, dem Namen des Feldes und <code>seed</code> ab: Kundennummer 4711 wird in jeder Zeile und in jeder Tabelle mit gleichem Feldnamen zu derselben Nummer. Wer den Seed kennt, kann Ersatzwerte durch Ausprobieren zurückführen – deshalb kommt er aus einer Umgebungsvariablen. Pseudonymisieren ersetzt nur die genannten Felder; Ort und Umsatz bleiben, die Daten sind also nicht anonym. <code>runnel validate</code> warnt bei <code>seed: ${PSEUDONYM_SEED}</code> „without seed, consistent uses seed 0“, weil die Prüfung den Wert der Variablen nicht kennt; im Lauf gilt der gesetzte Seed.','With <code>consistent: true</code> the replacement depends only on the input value, the field name and <code>seed</code>: customer number 4711 becomes the same number in every row and in every table with the same field name. Whoever knows the seed can trace replacements back by trying values – so it comes from an environment variable. Pseudonymizing replaces only the fields named; city and revenue stay, so the data is not anonymous. <code>runnel validate</code> warns “without seed, consistent uses seed 0” for <code>seed: ${PSEUDONYM_SEED}</code> because the check does not know the variable\'s value; the run uses the seed set.'),
  check=(FAKER_DE,FAKER_EN)),
]
T={'de':dict(eyebrow='Handbuch · Kochbuch',purpose='Zweck',api='API',auth='Anmeldung',prereq='Voraussetzungen',name='Name',kind='Art',meaning='Bedeutung',none='Keine Konten oder Schlüssel nötig.',files='Dateien',run='Ausführen',adapt='Anpassen',status='Stand',src='Quellen auf GitHub',run_hint='Im Ordner des Rezepts (PowerShell):',sec_hint='Secrets kommen hier aus Umgebungsvariablen (<code>secretStore: env</code> in <code>project.yaml</code>); für den Dienst die Variable beim Dienstkonto setzen. Ohne diese Zeile liest Runnel sie aus dem <a href="projekt.html#secret-store">lokalen Secret-Store</a>: <code>runnel secret set NAME</code>.'),
   'en':dict(eyebrow='User guide · Cookbook',purpose='Purpose',api='API',auth='Sign-in',prereq='Prerequisites',name='Name',kind='Kind',meaning='Meaning',none='No accounts or keys needed.',files='Files',run='Running',adapt='Adapting',status='Status',src='Sources on GitHub',run_hint='In the recipe folder (PowerShell):',sec_hint='Secrets come from environment variables here (<code>secretStore: env</code> in <code>project.yaml</code>); for the service, set the variable for the service account. Without this line Runnel reads them from the <a href="projekt.html#secret-store-en">local secret store</a>: <code>runnel secret set NAME</code>.')}
def article(r,lang):
    t=T[lang]; i=0 if lang=='de' else 1; sfx='' if lang=='de' else '-en'
    o=[f'<article class="prose" data-lang-block="{lang}" lang="{lang}">',
       f'<p class="docs-eyebrow">{t["eyebrow"]}</p>',f'<h1>{r["title"][i]}</h1>',f'<p class="docs-lead">{r["lead"][i]}</p>',
       f'<dl class="recipe-meta"><dt>{r.get("apiLabel",(t["api"],t["api"]))[i]}</dt><dd>{r["api"][i]}</dd><dt>{t["auth"]}</dt><dd>{r["auth"][i]}</dd><dt>{t["status"]}</dt><dd>{r.get("check",(CHECK_DE,CHECK_EN))[i]}</dd></dl>',
       f'<h2 id="prereq{sfx}">{t["prereq"]}</h2>']
    if r['prereq']:
        rows=''.join(f'<tr><td><code>{n}</code></td><td>{k}</td><td>{(d if lang=="de" else e)}</td></tr>' for n,k,d,e in r['prereq'])
        o.append(f'<div class="table-scroll"><table class="doc-table"><thead><tr><th>{t["name"]}</th><th>{t["kind"]}</th><th>{t["meaning"]}</th></tr></thead><tbody>{rows}</tbody></table></div>')
        if any(k=='Secret' for _,k,_,_ in r['prereq']): o.append(f'<p>{t["sec_hint"]}</p>')
    else: o.append(f'<p>{t["none"]}</p>')
    o.append(f'<h2 id="files{sfx}">{t["files"]}</h2>')
    for f in r['files']:
        o.append('{{snippet:../kochbuch/'+r['key']+'/'+f+'|'+f+'}}')
    if r['note']: o.append(f'<p>{r["note"][i]}</p>')
    o.append(f'<h2 id="run{sfx}">{t["run"]}</h2><p>{t["run_hint"]}</p>')
    o.append('<pre><code class="lang-bash" data-caption="PowerShell">'+html.escape('\n'.join(r['run']))+'</code></pre>')
    o.append(f'<h2 id="adapt{sfx}">{t["adapt"]}</h2><ul>'+''.join(f'<li>{a[i]}</li>' for a in r['adapt'])+'</ul>')
    o.append(f'<p class="docs-source"><a href="https://github.com/runnelhq/runnelhq.github.io/tree/main/_src/kochbuch/{r["key"]}">{t["src"]}: <code>_src/kochbuch/{r["key"]}</code></a></p>')
    o.append('</article>')
    return '\n          '.join(o)
for r in R:
    meta={"out":f"handbuch/kochbuch-{r['key']}.html","section":"guide","title":{"de":f"Kochbuch: {r['title'][0]}","en":f"Cookbook: {r['title'][1]}"},
          "description":{"de":re.sub('<[^>]+>','',r['lead'][0]) if False else html.unescape(__import__('re').sub('<[^>]+>','',r['lead'][0])),"en":html.unescape(__import__('re').sub('<[^>]+>','',r['lead'][1]))},
          "nav":"handbuch/","main_class":"docs-page"}
    page=f'<!-- {json.dumps(meta,ensure_ascii=False,indent=2)} -->\n    <div class="wrap docs-layout">\n      {{{{sidebar}}}}\n\n      <div class="docs-content">\n          {article(r,"de")}\n\n          {article(r,"en")}\n      </div>\n    </div>\n'
    open(OUT+f'guide-kochbuch-{r["key"]}.html','w').write(page)
    print('wrote',r['key'])
